package solution
import("regexp";"sort";"strings")
func HeaderNormalization(s string)(string,bool){if s==""{return "",false};k:=regexp.MustCompile(`^[A-Za-z][A-Za-z0-9]*(?:-[A-Za-z0-9]+)*$`);seen:=map[string]bool{};o:=[]string{};for _,x:=range strings.Split(s,","){if !k.MatchString(x){return "",false};n:=strings.ToLower(x);if seen[n]{return "",false};seen[n]=true;o=append(o,n)};sort.Strings(o);return strings.Join(o,","),true}
